-- ═══════════════════════════════════════════════════════════════
-- 0072: in-demand KEI / RR Kabel / Anchor house wires.
--
-- 32 wires from Google Merchant Center's demand report. No brand-store
-- API exists for these three, so pricing uses the demand report's own
-- observed market minimum (collected by Google from live merchants) − 2%.
-- Rows whose price-per-metre fell outside the plausible band for the size
-- were EXCLUDED as multi-coil pack prices rather than imported wrong.
--
-- mrp is deliberately set EQUAL to our price: we hold no verified list price
-- for these brands yet, and a fabricated MRP would be a false discount claim.
-- Backfill real MRPs from the brands' official price lists when available.
-- No images yet (storefront shows the category tile); brand imagery to follow.
-- ═══════════════════════════════════════════════════════════════

on conflict (id) do update set
  elume_price = excluded.elume_price, mrp = excluded.mrp, attrs = excluded.attrs, spec = excluded.spec;

select brand, count(*) from public.products
where brand in ('KEI','RR Kabel','Anchor') and category = 'Wires & Cables' group by 1;
